"""Freeze canonical-covered training and additive selection checks before cloud fitting."""
from pathlib import Path
import copy,hashlib,json
R=Path(__file__).resolve().parents[1];M=R/'model_evaluation';load=lambda p:json.loads(p.read_text())
for name in ['canonical-feature-cache-preflight.json','canonical-data-preflight.json','canonical-metrics-preflight.json']:
 proof=load(R/'results'/name);assert proof['passed'] and proof['optimizer_updates']==0
 for filename,digest in proof.get('source_sha256',{}).items() if isinstance(proof.get('source_sha256'),dict) else []:assert hashlib.sha256((M/filename).read_bytes()).hexdigest()==digest
assert load(R/'results/guard-matched-pilot04-no-allocation-proof.json')['passed']
assert not (R/'results/canonical-pilot01-execution.json').exists(),'Submitted protocol immutable'
old=load(R/'data/guard-matched-pilot04/trial-plan.json');p=copy.deepcopy(old);p['trial_identity']=dict(workflow='fds-gpu36-canonical01',label='gpu36-canonical01',prefix='density36/canonical-pilot01/',reservation_key='density36-canonical-pilot01')
p['arms']=['canonical_half','canonical_full'];p['canonical_loss_coefficients']=dict(canonical_half=.5,canonical_full=1.0)
p['risk_coefficients']={arm:dict(under_tail=.3,over_tail=.15) for arm in p['arms']}
p['training']['epochs_per_arm']=600
p['training']['extras']='Both arms retain matched aggregate quiet training, balanced under/over0.3/0.15, peak0.05, sampling0.1 and encoded nonharm0.25. Add canonical normalized physical endpoint MAE with weight0.5 or1.0; model architecture/initialization unchanged.'
p['training']['canonical_draws']='For every fit history/update draw a canonical horizon uniformly from1/4/8/16/45steps and origin uniformly over0..90-h; matched across arms. Every10epochs score all valid origins at all five horizons. Decode true lengths without fake padding. Fit-only physical error normalizers; inverse configuration replica weights timesNfit/Nconfig make the linear canonical estimator unbiased.'
p['training']['resume']='Actual CUDA serialized CPU-mapped restore must reproduce the next combined update with nonempty Adam moments. Every epoch/partial checkpoint retains model, optimizer, full RNG, epoch/cursor, permutation, original origin choices AND canonical horizon/origin choices, metric history and selection state. No automatic retry.'
p['canonical_acceptance']=dict(overall_each_state_relative_increase_at_most=.05,horizons_steps=[1,4,8,16,45],origins='All valid stride-one origins90/87/83/75/46',finite=True,phase_reporting='Report all four ScorecardV1 phase tables and actual durations; phase-specific changes require review, not hidden empty passes.')
p['evaluation']['eligible']='All original eligibility checks PLUS finite canonical forecasts and<=5percent overall MAE increase for each state at every canonical horizon. Raw fallback remains explicit. Initial context can fail the new guard.'
p['evaluation']['checkpoint_rule']='Use selection only. Require all original acceptance gates plus additive canonical checks, retaining original display-first rank and earlier-epoch tie. If none passes, best jointly guarded exploratory row or raw fallback; never call fallback accepted.'
p['evaluation']['winner_rule']='Only jointly selection-accepted arms eligible; same original rank with stable canonical_half-before-canonical_full tie. Freeze both selections/winner before previously examined development confirmation; do not switch using confirmation.'
p['budget_plan'].update(maximum_allowance_usd=1.3,workflow_cap_s=3600,vm_creation_age_cap_s=2850,task_cap_s=2730,training_soft_cap_s=2610,queue_cap_s=900,shutdown_margin_s=300,scope='One concurrent standard L4 under global GPUquota1. Whole3600second workflow plus300second cleanup at1.20USD/hour is1.30USD; shared charges retained project-level. No automatic task retry. All prior reservations including Flex40USD untouched.')
p['source_hashes'].pop('guard_matched_worker.py')
for name in ['canonical_worker.py','canonical_data.py','canonical_metrics.py','canonical_objective.py']:p['source_hashes'][name]=hashlib.sha256((M/name).read_bytes()).hexdigest()
p['canonical_cache_manifest_sha256']=hashlib.sha256((R/'results/canonical-feature-cache-prepared.json').read_bytes()).hexdigest()
p['prior_attempt']=dict(workflow='fds-gpu36-guardmatch04',result='Cancelled pending with no VM allocation after full-fit stride-one audit exposed short/long horizon regressions. Canonical training and selection coverage added; not a placement-only retry.')
p['scope']='Development comparison of canonical endpoint-loss weights0.5/1.0 on the same frozen GRU/context and timing residual. Existing full/autonomous/exact-gallery requirements retained, with every valid stride-one origin at1/4/8/16/45steps covered by training draws and selection/confirmation scoring. All original acceptance gates unchanged; additive5percent canonical state nonharm/finite guards. Both arms use balanced startup risk weights0.3/0.15. New loss normalization is fit-only; frozen older TRAIN-based base/feature normalization includes decoder-selection, so this is development transfer selection. Confirmation was previously examined and original test remains excluded. Same generic3m-diameter conical crowns4/6/8/10m high above2m base,1600weighted particles,0.5m mesh24x16x16m, imposed1500C contact ignition20s,180s histories near2s. No trunks/buildings/embers, convergence or real-material validation. Masses derived, gas sampled release not HRR, heating signed index not energy. Corrected outputs do not feed back to GRU. No fitted accuracy/deployment claim.'
assert p['acceptance']==old['acceptance'];assert (3600+300)*1.2/3600==1.3
p['status']='protocol_prepared_not_launched';p['implementation_status']='Combined canonical loss/scorer validated locally without optimizer updates; actual CUDA restore/fitting still pending.'
(R/'results/canonical-trial-plan.json').write_text(json.dumps(p,indent=2)+'\n');print('Canonical-covered protocol frozen; no cloud action')
